import { ChangeDetectionStrategy, Component, computed, contentChild, input, ViewEncapsulation } from '@angular/core';

import type { ClassValue } from 'clsx';

import { mergeClasses } from '@/shared/utils/merge-classes';

import {
  bubbleContentVariants,
  bubbleGroupVariants,
  bubbleReactionsVariants,
  bubbleVariants,
  type ZardBubbleAlignVariants,
  type ZardBubbleReactionsAlignVariants,
  type ZardBubbleReactionsSideVariants,
  type ZardBubbleVariantVariants,
} from './bubble.variants';

@Component({
  selector: 'z-bubble-group, [z-bubble-group]',
  template: '<ng-content />',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    'data-slot': 'bubble-group',
    '[class]': 'classes()',
  },
  exportAs: 'zBubbleGroup',
})
export class ZardBubbleGroupComponent {
  readonly class = input<ClassValue>('');

  protected readonly classes = computed(() => mergeClasses(bubbleGroupVariants(), this.class()));
}

@Component({
  selector: 'z-bubble-content, [z-bubble-content]',
  template: '<ng-content />',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    'data-slot': 'bubble-content',
    '[class]': 'classes()',
  },
  exportAs: 'zBubbleContent',
})
export class ZardBubbleContentComponent {
  readonly class = input<ClassValue>('');

  protected readonly classes = computed(() => mergeClasses(bubbleContentVariants(), this.class()));
}

@Component({
  selector: 'z-bubble, [z-bubble]',
  template: `
    <ng-content select="z-bubble-content, [z-bubble-content]" />
    <ng-content select="z-bubble-reactions, [z-bubble-reactions]" />
    @if (!hasContent()) {
      <div data-slot="bubble-content" [class]="contentClasses()">
        <ng-content />
      </div>
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    'data-slot': 'bubble',
    '[attr.data-variant]': 'zVariant()',
    '[attr.data-align]': 'zAlign()',
    '[class]': 'classes()',
  },
  exportAs: 'zBubble',
})
export class ZardBubbleComponent {
  readonly class = input<ClassValue>('');
  readonly zVariant = input<ZardBubbleVariantVariants>('default');
  readonly zAlign = input<ZardBubbleAlignVariants>('start');

  /**
   * A bubble with no `z-bubble-content` child gets the content surface for free, so
   * `<z-bubble>Hey there!</z-bubble>` is enough for a plain turn. Projecting the
   * content explicitly is what unlocks the rich cases — a `class` override, or the
   * whole turn rendered as a button or anchor.
   */
  private readonly projectedContent = contentChild(ZardBubbleContentComponent, { descendants: false });

  protected readonly hasContent = computed(() => !!this.projectedContent());
  protected readonly contentClasses = computed(() => bubbleContentVariants());
  protected readonly classes = computed(() =>
    mergeClasses(bubbleVariants({ zVariant: this.zVariant() }), this.class()),
  );
}

@Component({
  selector: 'z-bubble-reactions, [z-bubble-reactions]',
  template: '<ng-content />',
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  host: {
    'data-slot': 'bubble-reactions',
    '[attr.data-side]': 'zSide()',
    '[attr.data-align]': 'zAlign()',
    '[class]': 'classes()',
  },
  exportAs: 'zBubbleReactions',
})
export class ZardBubbleReactionsComponent {
  readonly class = input<ClassValue>('');
  readonly zSide = input<ZardBubbleReactionsSideVariants>('bottom');
  readonly zAlign = input<ZardBubbleReactionsAlignVariants>('end');

  protected readonly classes = computed(() =>
    mergeClasses(bubbleReactionsVariants({ zSide: this.zSide(), zAlign: this.zAlign() }), this.class()),
  );
}

export {
  ZardBubbleComponent,
  ZardBubbleContentComponent,
  ZardBubbleGroupComponent,
  ZardBubbleReactionsComponent,
} from './bubble.component';

import {
  ZardBubbleComponent,
  ZardBubbleContentComponent,
  ZardBubbleGroupComponent,
  ZardBubbleReactionsComponent,
} from './bubble.component';

export const ZardBubbleImports = [
  ZardBubbleGroupComponent,
  ZardBubbleComponent,
  ZardBubbleContentComponent,
  ZardBubbleReactionsComponent,
] as const;

import { cva, type VariantProps } from 'class-variance-authority';

import { mergeClasses } from '@/shared/utils/merge-classes';

export const bubbleGroupVariants = cva('flex min-w-0 flex-col gap-2');

export const bubbleVariants = cva('relative flex w-fit min-w-0 max-w-[80%] flex-col gap-1 data-[align=end]:self-end data-[variant=ghost]:max-w-full group-data-[align=end]/message:self-end group/bubble', {
  variants: {
    zVariant: {
      default: '*:data-[slot=bubble-content]:bg-primary *:data-[slot=bubble-content]:text-primary-foreground [&>[data-slot=bubble-content]:is(button,a):hover]:bg-primary/80',
      secondary: '*:data-[slot=bubble-content]:bg-secondary *:data-[slot=bubble-content]:text-secondary-foreground [&>[data-slot=bubble-content]:is(button,a):hover]:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)]',
      muted: '*:data-[slot=bubble-content]:bg-muted [&>[data-slot=bubble-content]:is(button,a):hover]:bg-[color-mix(in_oklch,var(--muted),var(--foreground)_5%)]',
      tinted: '*:data-[slot=bubble-content]:bg-[oklch(from_var(--primary)_0.93_calc(c*0.4)_h)] *:data-[slot=bubble-content]:text-foreground dark:*:data-[slot=bubble-content]:bg-[oklch(from_var(--primary)_0.3_calc(c*0.4)_h)] [&>[data-slot=bubble-content]:is(button,a):hover]:bg-[oklch(from_var(--primary)_0.88_calc(c*0.5)_h)] dark:[&>[data-slot=bubble-content]:is(button,a):hover]:bg-[oklch(from_var(--primary)_0.35_calc(c*0.5)_h)]',
      outline: '*:data-[slot=bubble-content]:border-border *:data-[slot=bubble-content]:bg-background [&>[data-slot=bubble-content]:is(button,a):hover]:bg-muted [&>[data-slot=bubble-content]:is(button,a):hover]:text-foreground dark:[&>[data-slot=bubble-content]:is(button,a):hover]:bg-input/30',
      ghost: 'border-none *:data-[slot=bubble-content]:rounded-none *:data-[slot=bubble-content]:bg-transparent *:data-[slot=bubble-content]:p-0 [&>[data-slot=bubble-content]:is(button,a):hover]:bg-muted [&>[data-slot=bubble-content]:is(button,a):hover]:text-foreground dark:[&>[data-slot=bubble-content]:is(button,a):hover]:bg-muted/50',
      destructive: '*:data-[slot=bubble-content]:bg-destructive/10 *:data-[slot=bubble-content]:text-destructive dark:*:data-[slot=bubble-content]:bg-destructive/20 [&>[data-slot=bubble-content]:is(button,a):hover]:bg-destructive/20 dark:[&>[data-slot=bubble-content]:is(button,a):hover]:bg-destructive/30',
    },
  },
  defaultVariants: {
    zVariant: 'default',
  },
});

export const bubbleContentVariants = cva('w-fit min-w-0 max-w-full overflow-hidden rounded-3xl border border-transparent px-3 py-2.5 text-sm/relaxed wrap-break-word group-data-[align=end]/bubble:self-end [button]:text-start [button,a]:transition-colors [button,a]:outline-none [button,a]:focus-visible:border-ring [button,a]:focus-visible:ring-3 [button,a]:focus-visible:ring-ring/30');

export const bubbleReactionsVariants = cva('absolute z-10 flex w-fit shrink-0 items-center justify-center gap-1 rounded-full bg-muted px-1.5 py-0.5 text-sm ring-3 ring-card has-[button]:p-0', {
  variants: {
    zSide: {
      top: 'top-0 -translate-y-3/4',
      bottom: 'bottom-0 translate-y-3/4',
    },
    zAlign: {
      start: 'start-3',
      end: 'end-3',
    },
  },
  defaultVariants: {
    zSide: 'bottom',
    zAlign: 'end',
  },
});

export type ZardBubbleVariantVariants = NonNullable<VariantProps<typeof bubbleVariants>['zVariant']>;
export type ZardBubbleAlignVariants = 'start' | 'end';
export type ZardBubbleReactionsSideVariants = NonNullable<VariantProps<typeof bubbleReactionsVariants>['zSide']>;
export type ZardBubbleReactionsAlignVariants = NonNullable<VariantProps<typeof bubbleReactionsVariants>['zAlign']>;

